function load<T,>(key:string,fallback:T):T{try{const x=localStorage.getItem(key);return x?JSON.parse(x) as T:fallback}catch{return fallback}}
function money(n:number,l:Lang,currency:Currency="DZD"){return new Intl.NumberFormat(l==="ar"?"ar-DZ":l==="fr"?"fr-DZ":"en-US",{style:"currency",currency,maximumFractionDigits:currency==="DZD"?0:2}).format(n)}
function advanceDate(value:string,cadence:"weekly"|"monthly"|"yearly"){const d=new Date(value+"T12:00:00");if(cadence==="weekly")d.setDate(d.getDate()+7);else if(cadence==="monthly"){const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last))}else d.setFullYear(d.getFullYear()+1);return d.toISOString().slice(0,10)}
