function categoryLabel(id:string,lang:Lang){const c=financeCategories.find(x=>x.id===id);return c?c[lang]:id}
function suggestCategory(value:string,lang:Lang){const text=value.toLocaleLowerCase();const found=financeCategories.find(c=>c.keywords.some(k=>text.includes(k.toLocaleLowerCase())));return found?found[lang]:categoryLabel("other",lang)}
