 const forecastRows=currencies.map(currency=>{const accounts=data.accounts.filter(a=>(a.currency||"DZD")===currency);if(!accounts.length)return null;const current=accounts.reduce((sum,a)=>sum+acctBal(a.id),0);const today=new Date();today.setHours(0,0,0,0);const todayKey=today.toISOString().slice(0,10);const since=new Date(today);since.setDate(since.getDate()-90);const history=data.transactions.filter(x=>(x.currency||"DZD")===currency&&x.date>=since.toISOString().slice(0,10));const dailyIncome=history.filter(x=>x.type==="income").reduce((v,x)=>v+x.amount,0)/90;const dailyExpense=history.filter(x=>x.type==="expense").reduce((v,x)=>v+x.amount,0)/90;return {currency,current,days:[30,60,90].map(days=>{const endDate=new Date(today);endDate.setDate(endDate.getDate()+days);const endKey=endDate.toISOString().slice(0,10);const bills=(data.bills||[]).filter(b=>!b.paid&&b.currency===currency&&b.due>=todayKey&&b.due<=endKey).reduce((v,b)=>v+b.amount,0);let scheduledIncome=0,scheduledExpense=0;(data.recurring||[]).filter(r=>r.currency===currency).forEach(r=>{let date=r.nextDate<todayKey?todayKey:r.nextDate;let guard=0;while(date<=endKey&&guard<100){if(r.type==="income")scheduledIncome+=r.amount;else scheduledExpense+=r.amount;date=advanceDate(date,r.cadence);guard++}});return {days,balance:current+(dailyIncome-dailyExpense)*days+scheduledIncome-scheduledExpense-bills}})}}).filter((x):x is NonNullable<typeof x>=>!!x);
