const healthMetrics=(()=>{const total=data.accounts.filter(a=>(a.currency||"DZD")==="DZD").reduce((sum,a)=>sum+Math.max(0,acctBal(a.id)),0);const reserves=safeSpend.filter(x=>x.currency==="DZD").reduce((sum,x)=>sum+x.obligations+x.budgetReserve+x.goalReserve,0);const liquidity=total?Math.max(0,Math.min(100,(total-reserves)/total*100)):0;const target=data.goals.reduce((sum,g)=>sum+g.target,0);const saved=data.goals.reduce((sum,g)=>sum+g.saved,0);const savings=target?Math.min(100,saved/target*100):50;const discipline=data.budgets.length?data.budgets.reduce((sum,b)=>sum+Math.min(1,spent(b.category)/Math.max(1,b.limit)),0)/data.budgets.length:0.5;return {score:Math.round(liquidity*.5+savings*.2+(1-discipline)*30),liquidity:Math.round(liquidity),savings:Math.round(savings),discipline:Math.round((1-discipline)*100)}})();
